using Atomic.Elements;using Atomic.Entities;using UnityEngine;namespace Game.Gameplay{    public static class WeaponUseCase    {        public static bool CanFireWithWeapon(this IGameEntity entity)        {            IWeaponEntity weapon = entity.GetWeapon().Value;            return weapon != null && weapon.GetFireCondition().Invoke();        }        public static void FireWithWeapon(this IGameEntity entity)        {            entity.GetWeapon().Value?.Fire();        }        public static bool CollectAmmoWithWeapon(this IGameEntity character, int amount)        {            if (!character.TryGetWeapon(out IReactiveVariable<IWeaponEntity> weaponVariable))                return false;            IWeaponEntity weapon = weaponVariable.Value;            if (weapon == null || !weapon.TryGetAmmo(out IVariable<int> ammo))                return false;            ammo.Value += amount;            return true;        }        public static bool DropWeapon(this IGameEntity character, IGameContext gameContext)        {            IVariable<IWeaponEntity> weaponVariable = character.GetWeapon();            IWeaponEntity weaponEntity = weaponVariable.Value;            if (weaponEntity == null)                return false;            GameEntity pickUpPrefab = weaponEntity.GetPickUpPrefab();            Vector3 spawnPosition = character.GetPosition().Value;            Quaternion spawnRotation = character.GetRotation().Value;            IPrefabEntityPool entityPool = gameContext.GetPrefabPool();            SceneEntity pickUpEntity = entityPool.Rent(pickUpPrefab, spawnPosition, spawnRotation);            foreach (string parameterKey in weaponEntity.GetDynamicParameterNames())            {                IValue source = weaponEntity.GetValue<IValue>(parameterKey);                ISetter destination = pickUpEntity.GetValue<ISetter>(parameterKey);                source.CopyTo(destination);            }            weaponEntity.GetOwner().Value = null;            weaponVariable.Value = null;            entityPool.Return(SceneEntity.Cast(weaponEntity));            return true;        }        public static bool PickUpWeapon(this IGameEntity character, IGameEntity pickUp, IGameContext context)        {            IVariable<IWeaponEntity> weaponVariable = character.GetWeapon();            if (weaponVariable.Value != null)                return false;            WeaponEntity weaponPrefab = pickUp.GetWeaponPrefab();            Transform transform = character.GetTransform();            IPrefabEntityPool entityPool = context.GetPrefabPool();            WeaponEntity weapon = (WeaponEntity) entityPool                .Rent(weaponPrefab, transform.position, transform.rotation, transform);            weapon.GetOwner().Value = character;            foreach (string parameterName in weapon.GetDynamicParameterNames())            {                IValue source = pickUp.GetValue<IValue>(parameterName);                ISetter destination = weapon.GetValue<ISetter>(parameterName);                source.CopyTo(destination);            }            weaponVariable.Value = weapon;            entityPool.Return(SceneEntity.Cast(pickUp));            return true;        }    }}